from rules import solve_versions


def solve(data):
    versions = solve_versions(
        data["packages"],
        data["roots"],
        data.get("blocked", {}),
        data.get("pins", {}),
        data.get("features", []),
    )
    if versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": versions}

def solve_versions(packages, roots, blocked=None, pins=None, features=None):
    if blocked is None:
        blocked = {}
    if pins is None:
        pins = {}
    if features is None:
        features = []

    package_names = sorted(packages)
    best_versions = None
    best_score = None

    def satisfies(version, ranges):
        return all(minimum <= version <= maximum for minimum, maximum in ranges)

    def active_dependencies(row):
        for dependency in row.get("deps", ()):
            feature = dependency.get("feature")
            if feature and feature not in features:
                continue
            yield dependency

    def is_acyclic(selected):
        state = {}

        def visit(name):
            current = state.get(name, 0)
            if current == 1:
                return False
            if current == 2:
                return True
            state[name] = 1
            row = next(
                row for row in packages[name]
                if row["version"] == selected[name]
            )
            for dependency in active_dependencies(row):
                if not visit(dependency["name"]):
                    return False
            state[name] = 2
            return True

        return all(visit(name) for name in selected)

    def visit(selected, required, constraints):
        nonlocal best_versions, best_score

        pending = sorted(required - selected.keys())
        if not pending:
            if not is_acyclic(selected):
                return
            score = tuple(selected.get(name, -1) for name in package_names)
            if best_score is None or score > best_score:
                best_score = score
                best_versions = dict(selected)
            return

        name = pending[0]
        forbidden = blocked.get(name, ())
        for row in packages.get(name, ()):
            version = row["version"]
            if version in forbidden or not satisfies(version, constraints.get(name, ())):
                continue
            if name in pins and version != pins[name]:
                continue

            next_selected = dict(selected)
            next_selected[name] = version
            next_required = set(required)
            next_constraints = {key: list(value) for key, value in constraints.items()}
            valid = True

            for dependency in active_dependencies(row):
                dep_name = dependency["name"]
                dep_range = (dependency["min"], dependency["max"])
                next_required.add(dep_name)
                next_constraints.setdefault(dep_name, []).append(dep_range)
                if dep_name in next_selected and not satisfies(
                    next_selected[dep_name], next_constraints[dep_name]
                ):
                    valid = False
                    break

            if valid:
                visit(next_selected, next_required, next_constraints)

    root_constraints = {
        name: [(minimum, maximum)] for name, (minimum, maximum) in roots.items()
    }
    visit({}, set(roots), root_constraints)

    if best_versions is None:
        return None
    return {name: best_versions[name] for name in sorted(best_versions)}
